fn capitalize_first_letter(word: Vec<char>) -> Vec<char> {
    // Since we own `word`, we can mutate it in place.
    let mut result = word;

    // If the first character is not an ASCII uppercase letter, replace it with 'A'.
    if !result[0].is_ascii_uppercase() {
        result[0] = 'A';
    }

    result
}

